import {drawStoryFrame,cleanStoryDesign} from './story-design.js';
import {downloadFile} from './experience.js';
import {makeKeepsakeArchive} from './keepsake.js';
import {createSound} from './audio-studio.js';
const blobOf=canvas=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Não foi possível gerar a imagem')),'image/png'));
export function initStoryExport({getData,authorize=async()=>true}){
 const panel=document.createElement('section');panel.className='story-export-panel';panel.innerHTML='<h3>Pronto para compartilhar.</h3><p>Exporte a capa, as fotos e o encerramento no formato vertical 1080 × 1920. O vídeo leva as imagens e o áudio escolhido; as surpresas interativas ficam no presente em HTML.</p><div><button type="button" class="export-story-images">Baixar imagens dos Stories</button><button type="button" class="export-story-video">Exportar vídeo · até 30 FPS</button><button type="button" class="cancel-story-export" hidden>Cancelar vídeo</button></div><progress max="100" value="0" hidden aria-label="Progresso da exportação"></progress><p class="story-export-status" role="status"></p>';document.querySelector('.digital-delivery').before(panel);
 let busy=false,controller=null;const status=panel.querySelector('.story-export-status'),progress=panel.querySelector('progress'),cancel=panel.querySelector('.cancel-story-export'),buttons=[panel.querySelector('.export-story-images'),panel.querySelector('.export-story-video')];
 const scenes=data=>[{kind:'cover'},...(data.photos||[]).map((photo,photoIndex)=>({kind:'photo',photoIndex,duration:photo.duration||cleanStoryDesign(data.storyDesign).duration})),{kind:'ending'}];
 function lock(value){busy=value;buttons.forEach(button=>button.disabled=value);}
 buttons[0].addEventListener('click',async()=>{if(busy||!await authorize())return;const data=structuredClone(getData());if(!data.photos?.length&&!data.recipient){status.textContent='Adicione suas fotos ou escreva para quem é o presente.';return;}lock(true);const canvas=document.createElement('canvas'),files=[];try{for(const [i,scene] of scenes(data).entries()){status.textContent='Preparando imagem '+(i+1)+'…';await drawStoryFrame(canvas,data,scene);files.push({name:'capimimo-stories/'+String(i+1).padStart(2,'0')+'.png',bytes:new Uint8Array(await(await blobOf(canvas)).arrayBuffer())});}downloadFile('capimimo-stories-1080x1920.zip',makeKeepsakeArchive(files));status.textContent='Stories prontos em PNG, 1080 × 1920. Extraia o ZIP e escolha as imagens para compartilhar.';}catch{status.textContent='Não foi possível exportar as imagens. Seu rascunho continua salvo.';}finally{canvas.width=canvas.height=1;lock(false);}});
 cancel.addEventListener('click',()=>controller?.abort());document.addEventListener('visibilitychange',()=>{if(document.hidden)controller?.abort();});addEventListener('pagehide',()=>controller?.abort());
 buttons[1].addEventListener('click',async()=>{if(busy||!await authorize())return;if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){status.textContent='Este navegador não exporta vídeo. Use a opção de imagens ou abra em um navegador compatível.';return;}const data=structuredClone(getData());if(!data.photos?.length){status.textContent='Adicione pelo menos uma foto para criar o vídeo.';return;}const mime=['video/mp4;codecs=avc1.42001E,mp4a.40.2','video/mp4','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(type=>MediaRecorder.isTypeSupported(type));if(!mime){status.textContent='Vídeo indisponível neste navegador. As imagens e o presente em HTML continuam disponíveis.';return;}
  lock(true);controller=new AbortController();const signal=controller.signal,canvas=document.createElement('canvas'),current=document.createElement('canvas'),next=document.createElement('canvas');canvas.width=1080;canvas.height=1920;const ctx=canvas.getContext('2d'),design=cleanStoryDesign(data.storyDesign),list=scenes(data),sound=createSound(data.experience||{},data.audioUrl);let recorder,stream,raf=0,finished=false;cancel.hidden=false;progress.hidden=false;progress.value=0;status.textContent='Preparando o vídeo. A exportação acontece em tempo real; mantenha esta aba aberta.';
  try{await drawStoryFrame(current,data,list[0]);ctx.drawImage(current,0,0);stream=canvas.captureStream(30);if(data.experience?.sound==='musicbox'||data.experience?.sound==='file'&&data.audioUrl){const audio=sound.recorderStream();audio?.getAudioTracks().forEach(track=>stream.addTrack(track));await sound.play();}const chunks=[];recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:3000000,audioBitsPerSecond:96000});const done=new Promise((resolve,reject)=>{recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data);};recorder.onerror=()=>reject(Error('Falha ao codificar vídeo'));recorder.onstop=()=>resolve(new Blob(chunks,{type:recorder.mimeType||mime}));});recorder.start(500);
   const durations=list.map(scene=>(scene.duration||3)*1000),total=durations.reduce((a,b)=>a+b,0);let completed=0;
   signal.addEventListener('abort',()=>{cancelAnimationFrame(raf);if(recorder.state!=='inactive')recorder.stop();},{once:true});
   for(let i=0;i<list.length&&!signal.aborted;i++){if(i)await drawStoryFrame(current,data,list[i]);if(i+1<list.length)await drawStoryFrame(next,data,list[i+1]);if(signal.aborted)break;const start=performance.now(),duration=durations[i];await new Promise(resolve=>{function tick(time){if(signal.aborted){resolve();return;}const elapsed=time-start;ctx.globalAlpha=1;ctx.drawImage(current,0,0);if(design.transition!=='cut'&&i+1<list.length&&elapsed>duration-350){const progress=Math.min(1,(elapsed-duration+350)/350);ctx.save();if(design.transition==='slide'){ctx.clearRect(0,0,1080,1920);ctx.drawImage(current,-1080*progress,0);ctx.drawImage(next,1080*(1-progress),0);}else if(design.transition==='zoom'){ctx.globalAlpha=progress;ctx.translate(540,960);const scale=.94+.06*progress;ctx.scale(scale,scale);ctx.drawImage(next,-540,-960);}else{ctx.globalAlpha=progress;ctx.drawImage(next,0,0);}ctx.restore();}progress.value=Math.min(100,(completed+Math.min(elapsed,duration))/total*100);status.textContent='Exportando '+Math.round(progress.value)+'% · '+Math.ceil((total-completed-elapsed)/1000)+' segundos restantes';if(elapsed<duration)raf=requestAnimationFrame(tick);else resolve();}raf=requestAnimationFrame(tick);signal.addEventListener('abort',resolve,{once:true});});completed+=duration;}
   if(recorder.state!=='inactive')recorder.stop();const blob=await done;if(!signal.aborted){if(!blob.size)throw Error('Vídeo vazio');downloadFile('capimimo-stories.'+(blob.type.includes('mp4')?'mp4':'webm'),blob);progress.value=100;status.textContent='Vídeo '+(blob.type.includes('mp4')?'MP4':'WebM')+' pronto · 1080 × 1920, até 30 FPS conforme o desempenho do aparelho. Use o arquivo baixado para compartilhar.';finished=true;}else status.textContent='Exportação cancelada. Seu presente continua no editor.';
  }catch{status.textContent=signal.aborted?'Exportação cancelada.':'O navegador não conseguiu concluir o vídeo. Você pode baixar as imagens e o presente em HTML.';}finally{cancelAnimationFrame(raf);if(recorder?.state!=='inactive')try{recorder?.stop();}catch{}stream?.getTracks().forEach(track=>track.stop());sound.stop();for(const surface of [canvas,current,next])surface.width=surface.height=1;cancel.hidden=true;if(!finished)progress.hidden=true;controller=null;lock(false);}
 });return {panel};
}
